const botaoMenu=document.querySelector(".alternador"),menu=document.getElementById("menu-principal");function alternarMenu(e){botaoMenu.setAttribute("aria-expanded",e),botaoMenu.classList.toggle("alternador--ativo",e),menu.classList.toggle("menu--aberto",e)}botaoMenu.addEventListener("click",()=>{alternarMenu("true"!==botaoMenu.getAttribute("aria-expanded"))}),menu.querySelectorAll(".menu__link").forEach(e=>e.addEventListener("click",()=>alternarMenu(!1))),document.addEventListener("keydown",e=>{"Escape"===e.key&&alternarMenu(!1)});const formulario=document.getElementById("formulario-contato"),retorno=document.getElementById("retorno-formulario");formulario.addEventListener("submit",e=>{if(e.preventDefault(),retorno.classList.remove("formulario__status--erro"),!formulario.checkValidity())return retorno.textContent="Preencha nome, um e-mail válido e a mensagem para enviar.",retorno.classList.add("formulario__status--erro"),void formulario.reportValidity();const t=formulario.nome.value.trim().split(" ")[0];retorno.textContent="Obrigado, "+t+"! Recebemos sua mensagem e responderemos em breve.",formulario.reset()});